using CareTogether.Application;
var builder = WebApplication.CreateBuilder(args); builder.Services.AddHealthChecks(); var app=builder.Build();
app.MapHealthChecks("/health");
app.MapPost("/api/ai/care-summary", (AiSummaryRequest r) => { var text=string.IsNullOrWhiteSpace(r.Context)?"No care context was supplied.":r.Context.Trim();var actions=new List<string>();if(text.Contains("MISSED task:",StringComparison.OrdinalIgnoreCase)||text.Contains("MISSED appointment:",StringComparison.OrdinalIgnoreCase)||text.Contains("MISSED medication:",StringComparison.OrdinalIgnoreCase))actions.Add("Review missed care items and coordinate follow-up with the Care Circle.");if(text.Contains("due",StringComparison.OrdinalIgnoreCase))actions.Add("Confirm today's assignments and medication administration status.");if(text.Contains("Next appointment:",StringComparison.OrdinalIgnoreCase))actions.Add("Review transportation, documents, and preparation for the next appointment.");if(actions.Count==0)actions.Add("Review this summary with the Care Circle and record any updates.");return Results.Ok(new AiSummaryResponse(text,actions,"AI assistance may be inaccurate, requires human review, and is not medical advice.")); });
app.MapPost("/api/ai/handoff-draft", (AiSummaryRequest r) => Results.Ok(new { summary=$"Draft handoff for review: {r.Context}", risks=new[]{"Verify allergies and recent medication changes"}, nextSteps=new[]{"Recipient must review and accept"}, disclaimer="Human review is required before sending." }));
app.Run();
